globalThis.ragSearchTexts=globalThis.ragSearchTexts||{};globalThis.ragSearchTexts["217"]={"1762":"Памятка об inplace в pandas\nБольшинство методов pd.DataFrame принимают аргумент inplace=True, который перезапишет переменную\ndata.replace(\" \", np.nan, inplace=True)\n\nКраткое описание:\nКороткая заметка по pandas: пример замены значений в DataFrame с аргументом inplace=True без отдельного присваивания результата."};
